//! Stable-only extractor of a crate's public surface, derived from source with `syn`.
//!
//! Known limits: items generated by macros are not seen, and glob re-exports are recorded
//! as written rather than expanded. Trait implementations are recorded wherever they appear
//! in a public module, whether or not the type is itself reachable.

use std::path::{Path, PathBuf};

use quote::ToTokens;
use syn::{Attribute, Expr, ExprLit, Fields, ImplItem, Item as SynItem, Lit, Meta, Visibility};

/// Reads a source file by path; injected so tests need no file system.
pub type Reader<'a> = &'a dyn Fn(&Path) -> Result<String, String>;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub path: String,
    pub kind: String,
    pub signature: String,
    pub is_type: bool,
    pub docs: Vec<String>,
}

impl Entry {
    pub fn line(&self) -> String {
        format!("{} {} {}", self.path, self.kind, self.signature)
            .trim_end()
            .to_string()
    }
}

struct Ctx<'a> {
    module: String,
    dir: PathBuf,
    read: Reader<'a>,
}

/// Scans a crate from its root file (`lib.rs`), following `mod` declarations.
pub fn scan_crate(root: &Path, read: Reader) -> Result<Vec<Entry>, String> {
    let mut out = Vec::new();
    scan_file(root, "crate", read, &mut out)?;
    out.sort_by_cached_key(Entry::line);
    out.dedup_by_key(|e| e.line());
    Ok(out)
}

fn scan_file(file: &Path, module: &str, read: Reader, out: &mut Vec<Entry>) -> Result<(), String> {
    let source = read(file)?;
    let parsed = syn::parse_file(&source).map_err(|e| format!("{}: {e}", file.display()))?;
    let stem = file
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or_default();
    let parent = file.parent().unwrap_or(Path::new(""));
    let dir = if matches!(stem, "lib" | "main" | "mod") {
        parent.to_path_buf()
    } else {
        parent.join(stem)
    };
    walk(
        &parsed.items,
        &Ctx {
            module: module.into(),
            dir,
            read,
        },
        out,
    )
}

fn walk(items: &[SynItem], ctx: &Ctx, out: &mut Vec<Entry>) -> Result<(), String> {
    for item in items.iter().filter(|i| !is_cfg_test(attrs_of(i))) {
        match item {
            SynItem::Mod(m) => walk_mod(m, ctx, out)?,
            SynItem::Impl(i) => describe_impl(i, &ctx.module, out),
            other => out.extend(describe(other, &ctx.module)),
        }
    }
    Ok(())
}

fn walk_mod(m: &syn::ItemMod, ctx: &Ctx, out: &mut Vec<Entry>) -> Result<(), String> {
    if !is_pub(&m.vis) {
        return Ok(());
    }
    if m.attrs.iter().any(|a| a.path().is_ident("path")) {
        return Err(format!(
            "`#[path]` on module `{}` is not supported by the API extractor",
            m.ident
        ));
    }
    out.push(entry(
        &ctx.module,
        &m.ident.to_string(),
        "mod",
        String::new(),
        &m.attrs,
    ));
    let module = format!("{}::{}", ctx.module, m.ident);
    if let Some((_, items)) = &m.content {
        let inner = Ctx {
            module,
            dir: ctx.dir.join(m.ident.to_string()),
            read: ctx.read,
        };
        return walk(items, &inner, out);
    }
    let flat = ctx.dir.join(format!("{}.rs", m.ident));
    let nested = ctx.dir.join(m.ident.to_string()).join("mod.rs");
    if (ctx.read)(&flat).is_ok() {
        scan_file(&flat, &module, ctx.read, out)
    } else {
        scan_file(&nested, &module, ctx.read, out)
            .map_err(|e| format!("cannot resolve module `{}`: {e}", m.ident))
    }
}

fn describe(item: &SynItem, module: &str) -> Option<Entry> {
    describe_data(item, module).or_else(|| describe_other(item, module))
}

fn describe_data(item: &SynItem, module: &str) -> Option<Entry> {
    match item {
        SynItem::Struct(s) if is_pub(&s.vis) => {
            let kind = kind_of("struct", &s.attrs);
            Some(entry(
                module,
                &s.ident.to_string(),
                &kind,
                struct_signature(s),
                &s.attrs,
            ))
        }
        SynItem::Enum(e) if is_pub(&e.vis) => {
            let kind = kind_of("enum", &e.attrs);
            Some(entry(
                module,
                &e.ident.to_string(),
                &kind,
                enum_signature(e),
                &e.attrs,
            ))
        }
        SynItem::Union(u) if is_pub(&u.vis) => {
            let sig = format!("{} {}", tokens(&u.generics), tokens(&u.fields));
            Some(entry(module, &u.ident.to_string(), "union", sig, &u.attrs))
        }
        SynItem::Type(t) if is_pub(&t.vis) => {
            let sig = format!("{} = {}", tokens(&t.generics), tokens(&t.ty));
            Some(entry(module, &t.ident.to_string(), "type", sig, &t.attrs))
        }
        SynItem::Trait(t) if is_pub(&t.vis) => Some(entry(
            module,
            &t.ident.to_string(),
            "trait",
            trait_signature(t),
            &t.attrs,
        )),
        _ => None,
    }
}

fn describe_other(item: &SynItem, module: &str) -> Option<Entry> {
    match item {
        SynItem::Fn(f) if is_pub(&f.vis) => Some(entry(
            module,
            &f.sig.ident.to_string(),
            "fn",
            tokens(&f.sig),
            &f.attrs,
        )),
        SynItem::Const(c) if is_pub(&c.vis) => Some(entry(
            module,
            &c.ident.to_string(),
            "const",
            tokens(&c.ty),
            &c.attrs,
        )),
        SynItem::Static(s) if is_pub(&s.vis) => Some(entry(
            module,
            &s.ident.to_string(),
            "static",
            tokens(&s.ty),
            &s.attrs,
        )),
        SynItem::Use(u) if is_pub(&u.vis) => {
            Some(entry(module, "{use}", "use", tokens(&u.tree), &u.attrs))
        }
        SynItem::Macro(m) if m.attrs.iter().any(|a| a.path().is_ident("macro_export")) => {
            let name = m
                .ident
                .as_ref()
                .map(ToString::to_string)
                .unwrap_or_default();
            Some(entry(module, &name, "macro", String::new(), &m.attrs))
        }
        _ => None,
    }
}

fn describe_impl(i: &syn::ItemImpl, module: &str, out: &mut Vec<Entry>) {
    let self_ty = tokens(&i.self_ty);
    if let Some((path, _)) = &i.trait_ {
        let sig = format!("{} {} for {self_ty}", tokens(&i.generics), tokens(path));
        out.push(entry(module, "{impl}", "impl", sig, &i.attrs));
        return;
    }
    let owner = format!("{module}::{self_ty}");
    for item in &i.items {
        out.extend(describe_impl_item(item, &owner));
    }
}

fn describe_impl_item(item: &ImplItem, owner: &str) -> Option<Entry> {
    match item {
        ImplItem::Fn(f) if is_pub(&f.vis) => Some(entry(
            owner,
            &f.sig.ident.to_string(),
            "fn",
            tokens(&f.sig),
            &f.attrs,
        )),
        ImplItem::Const(c) if is_pub(&c.vis) => Some(entry(
            owner,
            &c.ident.to_string(),
            "const",
            tokens(&c.ty),
            &c.attrs,
        )),
        ImplItem::Type(t) if is_pub(&t.vis) => Some(entry(
            owner,
            &t.ident.to_string(),
            "type",
            tokens(&t.ty),
            &t.attrs,
        )),
        _ => None,
    }
}

fn struct_signature(s: &syn::ItemStruct) -> String {
    let (fields, hidden) = public_fields(&s.fields);
    let rest = if hidden { ", .." } else { "" };
    format!("{} {{ {}{rest} }}", tokens(&s.generics), fields.join(", "))
}

fn public_fields(fields: &Fields) -> (Vec<String>, bool) {
    let mut shown = Vec::new();
    let mut hidden = false;
    for field in fields.iter() {
        if is_pub(&field.vis) {
            let name = field
                .ident
                .as_ref()
                .map(|i| format!("{i}: "))
                .unwrap_or_default();
            shown.push(format!("{name}{}", tokens(&field.ty)));
        } else {
            hidden = true;
        }
    }
    (shown, hidden)
}

fn enum_signature(e: &syn::ItemEnum) -> String {
    let variants: Vec<String> = e
        .variants
        .iter()
        .map(|v| {
            let mut v = v.clone();
            v.attrs.clear();
            tokens(&v)
        })
        .collect();
    format!("{} {{ {} }}", tokens(&e.generics), variants.join(", "))
}

fn trait_signature(t: &syn::ItemTrait) -> String {
    let items: Vec<String> = t
        .items
        .iter()
        .map(|item| match item {
            syn::TraitItem::Fn(f) => tokens(&f.sig),
            syn::TraitItem::Type(ty) => format!("type {}", ty.ident),
            syn::TraitItem::Const(c) => format!("const {}: {}", c.ident, tokens(&c.ty)),
            _ => String::new(),
        })
        .collect();
    format!(
        "{} : {} {{ {} }}",
        tokens(&t.generics),
        tokens(&t.supertraits),
        items.join("; ")
    )
}

fn entry(module: &str, name: &str, kind: &str, signature: String, attrs: &[Attribute]) -> Entry {
    Entry {
        path: format!("{module}::{name}"),
        kind: kind.into(),
        signature: signature.split_whitespace().collect::<Vec<_>>().join(" "),
        is_type: matches!(
            kind.split('[').next(),
            Some("struct" | "enum" | "union" | "type" | "trait")
        ),
        docs: doc_lines(attrs),
    }
}

fn kind_of(kind: &str, attrs: &[Attribute]) -> String {
    if attrs.iter().any(|a| a.path().is_ident("non_exhaustive")) {
        format!("{kind}[non_exhaustive]")
    } else {
        kind.into()
    }
}

fn tokens(node: &impl ToTokens) -> String {
    node.to_token_stream().to_string()
}

fn is_pub(vis: &Visibility) -> bool {
    matches!(vis, Visibility::Public(_))
}

fn is_cfg_test(attrs: &[Attribute]) -> bool {
    attrs
        .iter()
        .any(|a| a.path().is_ident("cfg") && tokens(&a.meta).replace(' ', "") == "cfg(test)")
}

fn attrs_of(item: &SynItem) -> &[Attribute] {
    match item {
        SynItem::Mod(i) => &i.attrs,
        SynItem::Impl(i) => &i.attrs,
        SynItem::Fn(i) => &i.attrs,
        SynItem::Struct(i) => &i.attrs,
        SynItem::Enum(i) => &i.attrs,
        SynItem::Use(i) => &i.attrs,
        _ => &[],
    }
}

fn doc_lines(attrs: &[Attribute]) -> Vec<String> {
    let mut lines = Vec::new();
    for attr in attrs.iter().filter(|a| a.path().is_ident("doc")) {
        if let Meta::NameValue(nv) = &attr.meta
            && let Expr::Lit(ExprLit {
                lit: Lit::Str(s), ..
            }) = &nv.value
        {
            lines.extend(s.value().lines().map(|l| l.trim().to_string()));
        }
    }
    lines
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    pub fn scan(files: &[(&str, &str)]) -> Result<Vec<Entry>, String> {
        let map: HashMap<PathBuf, String> = files
            .iter()
            .map(|(p, s)| (PathBuf::from(p), (*s).into()))
            .collect();
        let read = |p: &Path| {
            map.get(p)
                .cloned()
                .ok_or_else(|| format!("missing {}", p.display()))
        };
        scan_crate(Path::new("src/lib.rs"), &read)
    }

    fn lines(files: &[(&str, &str)]) -> Vec<String> {
        scan(files).unwrap().iter().map(Entry::line).collect()
    }

    #[test]
    fn private_items_are_not_recorded() {
        let out = lines(&[(
            "src/lib.rs",
            "fn a() {} pub(crate) fn b() {} pub fn c(x: u32) -> u32 { x }",
        )]);
        assert_eq!(out.len(), 1);
        assert!(out[0].starts_with("crate::c fn"));
    }

    #[test]
    fn making_an_item_public_changes_the_surface() {
        let before = lines(&[("src/lib.rs", "struct Hidden;")]);
        let after = lines(&[("src/lib.rs", "pub struct Hidden;")]);
        assert!(before.is_empty());
        assert_eq!(after.len(), 1);
    }

    #[test]
    fn modules_resolve_to_files_and_private_modules_are_skipped() {
        let out = lines(&[
            ("src/lib.rs", "pub mod a; mod b;"),
            ("src/a.rs", "pub struct A; pub mod deep;"),
            ("src/a/deep.rs", "pub fn f() {}"),
            ("src/b.rs", "pub struct Hidden;"),
        ]);
        assert!(out.iter().any(|l| l.starts_with("crate::a::A struct")));
        assert!(out.iter().any(|l| l.starts_with("crate::a::deep::f fn")));
        assert!(!out.iter().any(|l| l.contains("Hidden")));
    }

    #[test]
    fn test_modules_and_reexports() {
        let out = lines(&[(
            "src/lib.rs",
            "pub use a::B; #[cfg(test)] pub mod tests { pub fn t() {} }",
        )]);
        assert_eq!(out.len(), 1);
        assert!(out[0].contains("use a :: B"));
    }

    #[test]
    fn non_exhaustive_is_recorded_and_docs_are_captured() {
        let src = "/// Term: Finding\n#[non_exhaustive]\npub enum E { A, B(u8) }";
        let entries = scan(&[("src/lib.rs", src)]).unwrap();
        assert_eq!(entries[0].kind, "enum[non_exhaustive]");
        assert_eq!(entries[0].docs, vec!["Term: Finding"]);
        assert!(entries[0].is_type);
    }

    #[test]
    fn inherent_and_trait_impls_are_recorded() {
        let out = lines(&[(
            "src/lib.rs",
            "pub struct S; impl S { pub fn go(&self) {} fn no(&self) {} } impl Default for S { fn default() -> Self { S } }",
        )]);
        assert!(out.iter().any(|l| l.starts_with("crate::S::go fn")));
        assert!(!out.iter().any(|l| l.contains("::no ")));
        assert!(
            out.iter()
                .any(|l| l.contains("impl") && l.contains("Default for S"))
        );
    }

    #[test]
    fn unresolvable_module_is_an_error() {
        assert!(scan(&[("src/lib.rs", "pub mod ghost;")]).is_err());
    }
}
